tls:
set -eu
command -v openssl >/dev/null || { echo 'На сервере не найден openssl.' >&2; exit 1; }
command -v timeout >/dev/null || { echo 'На сервере не найден timeout.' >&2; exit 1; }
result="$(timeout 16 openssl s_client -connect '@@SNI@@:443' -servername '@@SNI@@' -tls1_3 -verify_return_error -verify_hostname '@@SNI@@' </dev/null 2>&1)" || { echo 'Не удалось подтвердить TLS 1.3 и сертификат выбранного имени с этого VPS.' >&2; exit 1; }
printf '%s' "$result" | grep -q 'TLSv1.3' || { echo 'TLS 1.3 не подтверждён.' >&2; exit 1; }
echo TLS_OK

updateStatus:
set -Eeuo pipefail
export LC_ALL=C
umask 077
fail() { printf '%s\n' "$*" >&2; exit 1; }
test "$(id -u)" = 0 || fail 'Нужны root или sudo без запроса пароля.'
job='/etc/bp-cascade/device-job.@@TX@@'
status="$(cat "$job/status" 2>/dev/null || true)"
case "$status" in
  SUCCESS) echo CLIENT_UPDATE_SUCCESS ;;
  FAILED) echo CLIENT_UPDATE_FAILED; tail -n 6 "$job/log" >&2 ;;
  *) echo CLIENT_UPDATE_PENDING ;;
esac
